#!/usr/bin/env node
/**
 * Reads shared/design-tokens.json (the single canonical, cross-stack token
 * source — see architecture doc §18/§21 and beauclick-core's PHP twin,
 * Support/Tokens.php) and emits:
 *   - src/design-system/tokens.generated.css  (CSS custom properties)
 *   - src/design-system/tokens.generated.ts   (typed JS constants, for logic
 *     that needs a token value in code, not just CSS — e.g. the AI FAB
 *     shadow-intensify-on-hover interaction)
 *
 * Both outputs are gitignored and regenerated by `npm run tokens`
 * (wired as predev/prebuild) — never hand-edit them, edit the JSON.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const __dirname = path.dirname( fileURLToPath( import.meta.url ) );
const tokensPath = path.resolve( __dirname, '../../shared/design-tokens.json' );
const outDir = path.resolve( __dirname, '../src/design-system' );

const tokens = JSON.parse( readFileSync( tokensPath, 'utf-8' ) );

const kebab = ( camel ) => camel.replace( /(?<!^)[A-Z]/g, ( m ) => `-${ m.toLowerCase() }` );

const cssLines = [ '/* AUTO-GENERATED by scripts/generate-tokens-css.mjs — do not edit. Edit shared/design-tokens.json instead. */', ':root {' ];
const tsColor = {};
const tsRadius = {};
const tsSpacing = {};

for ( const [ name, def ] of Object.entries( tokens.color ?? {} ) ) {
	cssLines.push( `  --bc-color-${ kebab( name ) }: ${ def.value };` );
	tsColor[ name ] = def.value;
	if ( def.soft ) {
		cssLines.push( `  --bc-color-${ kebab( name ) }-soft: ${ def.soft };` );
		tsColor[ `${ name }Soft` ] = def.soft;
	}
}

for ( const [ name, value ] of Object.entries( tokens.radius ?? {} ) ) {
	cssLines.push( `  --bc-radius-${ kebab( name ) }: ${ value };` );
	tsRadius[ name ] = value;
}

for ( const [ name, value ] of Object.entries( tokens.spacing ?? {} ) ) {
	cssLines.push( `  --bc-space-${ kebab( name ) }: ${ value };` );
	tsSpacing[ name ] = value;
}

for ( const [ name, value ] of Object.entries( tokens.shadow ?? {} ) ) {
	cssLines.push( `  --bc-shadow-${ kebab( name ) }: ${ value };` );
}

if ( tokens.typography?.fontFamily ) {
	cssLines.push( `  --bc-font-family: ${ tokens.typography.fontFamily };` );
}
if ( tokens.gradient?.brand ) {
	cssLines.push( `  --bc-gradient-brand: ${ tokens.gradient.brand };` );
}
if ( tokens.spacing?.contentMaxWidth ) {
	cssLines.push( `  --bc-content-max-width: ${ tokens.spacing.contentMaxWidth };` );
}
if ( tokens.breakpoint?.mobile ) {
	cssLines.push( `  --bc-breakpoint-mobile: ${ tokens.breakpoint.mobile };` );
}

cssLines.push( '}' );
cssLines.push( '' );
cssLines.push( '[dir="rtl"] { direction: rtl; }' );

writeFileSync( path.join( outDir, 'tokens.generated.css' ), cssLines.join( '\n' ) + '\n' );

const ts = `// AUTO-GENERATED by scripts/generate-tokens-css.mjs — do not edit. Edit shared/design-tokens.json instead.
export const color = ${ JSON.stringify( tsColor, null, 2 ) } as const;
export const radius = ${ JSON.stringify( tsRadius, null, 2 ) } as const;
export const spacing = ${ JSON.stringify( tsSpacing, null, 2 ) } as const;
export const breakpointMobile = ${ JSON.stringify( tokens.breakpoint?.mobile ?? '900px' ) };
`;

writeFileSync( path.join( outDir, 'tokens.generated.ts' ), ts );

console.log( '[tokens] generated tokens.generated.css + tokens.generated.ts from shared/design-tokens.json' );
